 private frame(a:Attachment){const point=a.body.getWorldPoint(Vec2(a.point.x,a.point.y)),out=a.body.getWorldVector(Vec2(a.normal.x,a.normal.y));return{body:a.body,point,out,tangent:Vec2(-out.y,out.x)};}
