class Surface{listeners=new Map<string,((e:any)=>void)[]>();addEventListener(type:string,fn:(e:any)=>void){this.listeners.set(type,[...(this.listeners.get(type)??[]),fn]);}emit(type:string,event:any={}){for(const fn of this.listeners.get(type)??[])fn({target:this,preventDefault(){},...event});}capture:number|null=null;setPointerCapture(id:number){this.capture=id;}hasPointerCapture(id:number){return this.capture===id;}releasePointerCapture(){this.capture=null;}}
