const hash=(v:string|Buffer)=>createHash('sha256').update(v).digest('hex');
test('visual experiment preserves every approved server, simulation, AI, audio and input byte',()=>{const m=JSON.parse(readFileSync('docs/creative-identity/preservation.json','utf8'));assert.equal(m.baseline,'5da8bac60044643bdded2db7331052c56692ca4c');for(const[p,x]of Object.entries(m.protected))assert.equal(hash(cosmeticOptionsPreservedSource(p,true)),x,p);for(const[p,r]of Object.entries(m.files)as[string,any][]){assert.equal(hash(r.original),r.beforeSha256,p);assert.equal(hash(cosmeticOptionsPreservedSource(p,true)),r.afterSha256,p);assert.ok(['index.html','src/main.ts','src/presentation/cosmetic-art.ts','src/presentation/courtyard.ts','src/ui/arena-preview.ts','src/ui/chaos-ui.ts','src/ui/lobby-visuals.ts'].includes(p),p);}const main=m.files['src/main.ts'];assert.equal(readFileSync('src/main.ts','utf8').replace("import './presentation/creative.css';\n",''),main.original);});
test('every original HTML control ID remains present once with its original semantic element',()=>{const m=JSON.parse(readFileSync('docs/creative-identity/preservation.json','utf8')),before=m.files['index.html'].original,after=readFileSync('index.html','utf8');const ids=(s:string)=>[...s.matchAll(/<([\w-]+)\b[^>]*\bid="([^"]+)"/g)].map(v=>[v[1],v[2]]);assert.deepEqual(ids(after),ids(before));assert.match(after,/viewport-fit=cover/);});
for(const a of arenaList)test(`printed ${a.name} draws every exact collision silhouette and supports local filtered platform rendering`,()=>{const polygons:any[]=[],methods=new Set(['fillPoints','strokePoints']);const g=new Proxy({},{get:(_,key:string)=>key==='then'?undefined:(...args:any[])=>{if(methods.has(key))polygons.push({kind:key,points:args[0].map((p:any)=>({...p}))});}});paintPrintedArena(g as any,a,{background:false});for(const r of a.solids){const pts=r.outline?r.outline.map(([px,py])=>({x:(r.x+px)*30,y:(r.y+py)*30})):[{x:(r.x-r.w/2)*30,y:(r.y-r.h/2)*30},{x:(r.x+r.w/2)*30,y:(r.y-r.h/2)*30},{x:(r.x+r.w/2)*30,y:(r.y+r.h/2)*30},{x:(r.x-r.w/2)*30,y:(r.y+r.h/2)*30}];assert.ok(polygons.some(p=>p.kind==='fillPoints'&&p.points.length===pts.length&&p.points.every((q:any,i:number)=>Math.abs(q.x-pts[i].x)<1e-8&&Math.abs(q.y-pts[i].y)<1e-8)),JSON.stringify(r));}const local={...a,solids:a.solids.map((r,i)=>({...r,x:i===4?0:r.x,y:i===4?0:r.y}))};polygons.length=0;paintPrintedArena(g as any,local,{background:false,filter:i=>i===4});assert.equal(polygons.filter(p=>p.kind==='fillPoints').length,1);});
test('all cosmetic combinations keep accessible identities, eyes, hats and an open-mouth home variant',()=>{for(const skin of SKINS)for(const eyes of EYES)for(const hat of HATS){const a={skin:skin.id,eyes:eyes.id,hat:hat.id},svg=appearancePreview(a);assert.match(svg,/viewBox="0 0 120 100"/);assert.ok(svg.includes(skin.name));assert.ok(svg.includes(eyes.id));assert.match(svg,/role="img"/);assert.ok(!svg.includes('undefined'));assert.notEqual(appearancePreview(a,true),svg);}});
