 const frog=cosmeticOptionsPreservedSource('src/presentation/courtyard.ts') as string;assert.match(frog,/bodyColor=layers.skin.color/);assert.match(frog,/fillStyle\(0xffffff,.28\)/);
});

test('gameplay Daisy petals and center have closed ink outlines without changing their silhouette',()=>{const circles:any[]=[],styles:any[]=[];const g=new Proxy({},{get:(_,key:string)=>(...args:any[])=>{if(key==='lineStyle')styles.push(args);if(key==='fillCircle'||key==='strokeCircle')circles.push({key,args});}});paintHat(g as any,10,20,12,'flower',0);const filled=circles.filter(c=>c.key==='fillCircle'),outlined=circles.filter(c=>c.key==='strokeCircle');assert.equal(filled.length,6);assert.deepEqual(outlined.map(c=>c.args),filled.map(c=>c.args));assert.ok(styles.some(([w,c])=>w>0&&c===0x292431));assert.equal(filled.at(-1).args[2],4*12/38.5);});

